 clarify=['Data types: small records (notes) or large blobs (photos)?','Offline edits required?','Conflict policy: last-writer-wins, merge, or ask the user?','End-to-end encryption required?'],
 reqs=dict(functional=['Edit offline, sync when online','Sync across many devices of one user','Efficient delta sync'],nonfunctional=['No data loss on conflicts','Battery and bandwidth friendly','End-to-end encryption for sensitive data']),
